//! 🏭️ A retained Source close producer owns its original roots and authentic payer loan.
use super::*;
use semio_framework_value_control_contract::{OriginalEffectAuthority,OriginalEffectProducer,OriginalEffectReply,OriginalEffectReplyComplete,OriginalEffectInvocationIdentity,OriginalEffectCallbackMode,OriginalSourceTurnIdentity,RetainedAllocationEffect,RetainedWorkPoll};

trait CloseContextAccess{fn validate_close_payer(&self,payer:&OriginalCallerSourceLoan)->Result<(),ValueError>;fn close_source_turn(&self)->Option<OriginalSourceTurnIdentity>;}
impl CloseContextAccess for semio_framework_value_control_contract::RetainedOwnerGate<&mut StepContext<'_>>{fn validate_close_payer(&self,payer:&OriginalCallerSourceLoan)->Result<(),ValueError>{let cx=self.try_lock().map_err(|_|ValueError::invariant("original Source context is busy"))?;payer.validate_retirement_context(&cx)}fn close_source_turn(&self)->Option<OriginalSourceTurnIdentity>{self.try_lock().ok().and_then(|cx|cx.original_source_turn_identity())}}
/// 🧭️ Borrows the actual Source context briefly and releases it before child callbacks.
pub struct OriginalSourceCloseContext<'view>{context:&'view(dyn CloseContextAccess+'view)}
impl<'view> OriginalSourceCloseContext<'view>{
 pub fn new<'turn:'view,'source:'view>(context:&'view semio_framework_value_control_contract::RetainedOwnerGate<&'turn mut StepContext<'source>>)->Self{Self{context}}
 fn validate_close_payer(&self,payer:&OriginalCallerSourceLoan)->Result<(),ValueError>{self.context.validate_close_payer(payer)}
 fn close_source_turn(&self)->Option<OriginalSourceTurnIdentity>{self.context.close_source_turn()}
}

/// 🧳️ Keeps the same Source and paid payer loan across every close callback.
pub struct OriginalSourceCloseProducer{source:ManuallyDrop<Option<OriginalCallerSourceParent>>,payer:ManuallyDrop<Option<OriginalCallerSourceLoan>>,action:Option<OriginalEffectInvocationIdentity>,recorded:ManuallyDrop<Option<Result<RetainedCloneStep,OriginalSourceCloseFailure>>>,clock_reply:ManuallyDrop<Option<Result<RetainedCloneStep,semio_framework_value_retained_clone::OriginalRetirementFailure>>>}
impl OriginalSourceCloseProducer{
 /// 📏️ Quotes moving the actual Source, payer and producer authority into resident slots.
 pub fn admission_demand()->RetirementDemand{RetirementDemand{copy_bytes:size_of::<Option<OriginalCallerSourceParent>>()+size_of::<Option<OriginalCallerSourceLoan>>()+size_of::<Option<OriginalEffectAuthority<Self>>>(),depth:1,..Default::default()}}
 /// 🏠️ Admits only the original owners after authenticating their real payer and Work.
 pub fn admit(source:&mut Option<OriginalCallerSourceParent>,payer:&mut Option<OriginalCallerSourceLoan>,output:&mut Option<OriginalEffectAuthority<Self>>,cx:&StepContext<'_>,effect:&mut RetainedAllocationEffect<'_>)->RetainedWorkOutcome<Option<RetainedCloneProgress>,ValueError>{
  let fail=|error|RetainedWorkOutcome{result:Err(error),work:0};if output.is_some(){return fail(refused("Source close producer slot is occupied"))}let Some(original)=source.as_ref()else{return fail(refused("Source close owner is absent"))};if original.terminal_is_empty(){return fail(refused("Source close owner is already terminal"))}let Some(loan)=payer.as_ref()else{return fail(refused("Source close payer loan is absent"))};if let Err(error)=loan.validate_retirement_context(cx){return fail(error)}if cx.original_source_turn_identity().is_none()||effect.work_source_turn()!=cx.original_source_turn_identity(){return fail(refused("Source close payer does not match original Work"))}if original.original.is_some(){let source_identity=match original.source_identity(){Ok(value)=>value,Err(error)=>return fail(error)};let payer_identity=match loan.source_identity(){Ok(value)=>value,Err(error)=>return fail(error)};if source_identity==payer_identity{return fail(refused("Source close payer retains the Source being closed"))}}let demand=Self::admission_demand();let remaining=match effect.remaining_work_units(){Ok(value)=>value,Err(error)=>return fail(error)};if remaining==0||!semio_framework_value_retained_clone::retained_clone::retained_clone_grant_admits(effect.grant(),demand){return RetainedWorkOutcome{result:Ok(None),work:0}}match effect.performed(1){Ok(true)=>{},Ok(false)=>return RetainedWorkOutcome{result:Err(ValueError::literal(ValueRefusalKind::WorkLimit,"Source close producer admission exceeded its Work grant")),work:1},Err(error)=>return fail(error)}let owner=Self{source:ManuallyDrop::new(source.take()),payer:ManuallyDrop::new(payer.take()),action:None,recorded:ManuallyDrop::new(None),clock_reply:ManuallyDrop::new(None)};*output=Some(OriginalEffectAuthority::new(owner));RetainedWorkOutcome{result:Ok(Some(RetainedCloneProgress{copied_items:1,copied_bytes:demand.copy_bytes,..Default::default()})),work:1}
 }
 /// 🔎️ Observes terminal roots while the authority independently retains its action.
 pub fn source_is_closed(&self)->bool{self.action.is_none()&&self.recorded.is_none()&&self.clock_reply.is_none()&&self.source.as_ref().is_some_and(OriginalCallerSourceParent::terminal_is_empty)}
 /// 📏️ Quotes the next actual Source stage before starting its original action.
 pub fn demand(&self,cx:&StepContext<'_>)->Result<(RetirementDemand,u64),ValueError>{if self.action.is_some()||self.recorded.is_some()||self.clock_reply.is_some(){return Err(refused("Source close action retains its original quote"))}let payer=self.payer.as_ref().ok_or_else(||refused("Source close payer loan is absent"))?;payer.validate_retirement_context(cx)?;if cx.original_source_turn_identity().is_none(){return Err(refused("Source close payer has no original turn"))}let source=self.source.as_ref().ok_or_else(||refused("Source close owner is absent"))?;Ok((source.retirement_demands()?,source.retirement_work_demand()?))}
 /// 📏️ Quotes returning both original owners from the idle producer.
 pub fn return_demand()->RetirementDemand{RetirementDemand{copy_bytes:size_of::<Option<OriginalCallerSourceParent>>()+size_of::<Option<OriginalCallerSourceLoan>>() + size_of::<Option<Self>>(),depth:1,..Default::default()}}
 /// 📤️ Transfers the same Source and live payer directly to their caller slots.
 pub fn return_owners(slot:&mut Option<Self>,source:&mut Option<OriginalCallerSourceParent>,payer:&mut Option<OriginalCallerSourceLoan>,cx:&StepContext<'_>,effect:&mut RetainedAllocationEffect<'_>)->RetainedWorkOutcome<Option<RetainedCloneProgress>,ValueError>{
  let fail=|error|RetainedWorkOutcome{result:Err(error),work:0};if source.is_some()||payer.is_some(){return fail(refused("Source close return slot is occupied"))}let Some(owner)=slot.as_ref()else{return RetainedWorkOutcome{result:Ok(None),work:0}};if owner.action.is_some()||owner.recorded.is_some()||owner.clock_reply.is_some(){return fail(refused("Source close action or reply remains live"))}if owner.source.is_none(){return fail(refused("Source close owner is absent"))}let Some(loan)=owner.payer.as_ref()else{return fail(refused("Source close payer loan is absent"))};if let Err(error)=loan.validate_retirement_context(cx){return fail(error)}if cx.original_source_turn_identity().is_none()||effect.work_source_turn()!=cx.original_source_turn_identity(){return fail(refused("Source close return changed original Work"))}let demand=Self::return_demand();let remaining=match effect.remaining_work_units(){Ok(value)=>value,Err(error)=>return fail(error)};if remaining==0||!semio_framework_value_retained_clone::retained_clone::retained_clone_grant_admits(effect.grant(),demand){return RetainedWorkOutcome{result:Ok(None),work:0}}match effect.performed(1){Ok(true)=>{},Ok(false)=>return RetainedWorkOutcome{result:Err(ValueError::literal(ValueRefusalKind::WorkLimit,"Source close return exceeded its Work grant")),work:1},Err(error)=>return fail(error)}let mut owner=slot.take().expect("Source close producer slot checked");*source=owner.source.take();*payer=owner.payer.take();drop(owner);RetainedWorkOutcome{result:Ok(Some(RetainedCloneProgress{copied_items:1,copied_bytes:demand.copy_bytes,..Default::default()})),work:1}
 }
 fn advance(&mut self,cx:&OriginalSourceCloseContext<'_>,effect:&mut RetainedAllocationEffect<'_>)->Result<RetainedWorkPoll<RetainedCloneStep,OriginalSourceCloseFailure>,ValueError>{let payer=self.payer.as_ref().ok_or_else(||refused("Source close payer loan is absent"))?;cx.validate_close_payer(payer)?;let source=self.source.as_mut().ok_or_else(||refused("Source close owner is absent"))?;let witness=if source.borrowed_cancel{Some(payer.cancellation()?)}else{None};Ok(source.close_witnessed(effect,witness))}
 fn drive<'reply>(&mut self,cx:&OriginalSourceCloseContext<'_>,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'reply,RetainedCloneStep,OriginalSourceCloseFailure>,expected:OriginalEffectCallbackMode)->Result<OriginalEffectReplyComplete<'reply,RetainedCloneStep,OriginalSourceCloseFailure>,ValueError>{let invocation=effect.invocation().ok_or_else(||refused("Source close has no original invocation"))?;if invocation.mode()!=expected{return Err(refused("Source close invocation phase changed"))}let identity=invocation.identity();if expected==OriginalEffectCallbackMode::Receive{if self.action.is_some()||self.recorded.is_some()||self.clock_reply.is_some(){return Err(refused("Source close action slot is occupied"))}self.action=Some(identity)}else if self.action!=Some(identity){return Err(refused("Source close recovery changed original invocation"))}if let Some(result)=self.recorded.take(){self.action=None;return Ok(reply.complete(result))}
  if let Some(result)=self.clock_reply.take(){self.action=None;return Ok(reply.complete(result.map(|step|RetainedCloneStep::Progress(step.progress())).map_err(OriginalSourceCloseFailure::Retirement)))}
  let payer=self.payer.as_ref().ok_or_else(||refused("Source close payer loan is absent"))?;cx.validate_close_payer(payer)?;let source=self.source.as_mut().ok_or_else(||refused("Source close owner is absent"))?;if source.clock_retirement_selected()?{let child=OriginalEffectReply::borrow(&mut self.clock_reply)?;let done=source.close_clock_retirement_into(effect,child,expected==OriginalEffectCallbackMode::Recover)?;drop(done);if let Some(result)=self.clock_reply.take(){self.action=None;return Ok(reply.complete(result.map(|step|RetainedCloneStep::Progress(step.progress())).map_err(OriginalSourceCloseFailure::Retirement)))}return Ok(reply.pending())}
  if expected==OriginalEffectCallbackMode::Recover{return Ok(reply.pending())}if self.recorded.is_none(){match self.advance(cx,effect)?{RetainedWorkPoll::Pending{..}=>return Ok(reply.pending()),RetainedWorkPoll::Complete(turn)=>*self.recorded=Some(turn.result)}}let result=self.recorded.take().ok_or_else(||refused("Source close recorded reply is absent"))?;self.action=None;Ok(reply.complete(result))}
}
impl OriginalEffectProducer for OriginalSourceCloseProducer{
 type Output=RetainedCloneStep;type Failure=OriginalSourceCloseFailure;type Context<'turn,'source>=OriginalSourceCloseContext<'turn> where 'source:'turn;
 fn validate_context<'turn,'source>(&self,cx:&Self::Context<'turn,'source>)->Result<(),ValueError> where 'source:'turn{if cx.close_source_turn().is_none(){return Err(refused("Source close payer has no original turn"))}cx.validate_close_payer(self.payer.as_ref().ok_or_else(||refused("Source close payer loan is absent"))?)}
 fn source_turn<'turn,'source>(&self,cx:&Self::Context<'turn,'source>)->Option<OriginalSourceTurnIdentity> where 'source:'turn{cx.close_source_turn()}
 fn receive<'reply,'turn,'source>(&mut self,cx:&mut Self::Context<'turn,'source>,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'reply,Self::Output,Self::Failure>)->Result<OriginalEffectReplyComplete<'reply,Self::Output,Self::Failure>,ValueError> where 'source:'turn{self.drive(cx,effect,reply,OriginalEffectCallbackMode::Receive)}
 fn recover<'reply,'turn,'source>(&mut self,cx:&mut Self::Context<'turn,'source>,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'reply,Self::Output,Self::Failure>)->Result<OriginalEffectReplyComplete<'reply,Self::Output,Self::Failure>,ValueError> where 'source:'turn{self.drive(cx,effect,reply,OriginalEffectCallbackMode::Recover)}
}
impl Drop for OriginalSourceCloseProducer{fn drop(&mut self){assert!(std::thread::panicking()||self.source.is_none()&&self.payer.is_none()&&self.action.is_none()&&self.recorded.is_none()&&self.clock_reply.is_none(),"original Source close producer requires paid owner return")}}

/// 📏️ Quotes the actual Source loan and borrowed-parent output slots.
pub fn source_loan_transfer_demand()->RetirementDemand{RetirementDemand{copy_bytes:size_of::<Option<OriginalCallerSourceLoan>>()+size_of::<Option<OriginalCallerSourceParent>>(),depth:1,..Default::default()}}
fn admit_source_loan_transfer(cx:&StepContext<'_>,effect:&mut RetainedAllocationEffect<'_>)->Result<bool,(ValueError,u128)>{let source=cx.original_source_turn_identity().ok_or_else(||(refused("Source transfer has no original turn"),0))?;if effect.work_source_turn()!=Some(source){return Err((refused("Source transfer changed original Work"),0))}let remaining=effect.remaining_work_units().map_err(|error|(error,0))?;if remaining==0||!semio_framework_value_retained_clone::retained_clone::retained_clone_grant_admits(effect.grant(),source_loan_transfer_demand()){return Ok(false)}match effect.performed(1){Ok(true)=>Ok(true),Ok(false)=>Err((ValueError::literal(ValueRefusalKind::WorkLimit,"Source transfer exceeded its Work grant"),1)),Err(error)=>Err((error,0))}}
impl OriginalCallerSourceLoan{
 /// ⏱️ Settles the exact same-Source Core receipt before returning its borrowed reply.
 pub fn settle_original_work<'receipt>(&self,cx:&mut StepContext<'_>,check:semio_framework_value_control_contract::OriginalWorkPartialCheck<'receipt>)->semio_framework_value_control_contract::OriginalWorkPartialCheckComplete<'receipt>{let result=(||{self.validate_retirement_context(cx)?;let turn=cx.original_source_turn_identity().ok_or_else(||refused("original Source Work turn is absent"))?;if check.source_turn()!=Some(turn){return Err(refused("original Source Work receipt changed its turn"))}cx.settle_original_work_exact(check.delta())})();check.complete(result)}
 /// 📤️ Moves the same live paid loan into its borrowed-parent slot under original Work.
 pub fn transfer_borrowed_parent(slot:&mut Option<Self>,output:&mut Option<OriginalCallerSourceParent>,cx:&StepContext<'_>,effect:&mut RetainedAllocationEffect<'_>)->RetainedWorkOutcome<Option<RetainedCloneProgress>,ValueError>{let fail=|error|RetainedWorkOutcome{result:Err(error),work:0};if output.is_some(){return fail(refused("borrowed Source parent output is occupied"))}let Some(loan)=slot.as_ref()else{return RetainedWorkOutcome{result:Ok(None),work:0}};if let Err(error)=loan.validate_context(cx){return fail(error)}match admit_source_loan_transfer(cx,effect){Ok(true)=>{},Ok(false)=>return RetainedWorkOutcome{result:Ok(None),work:0},Err((error,work))=>return RetainedWorkOutcome{result:Err(error),work}}let loan=slot.take().expect("validated original Source loan");*output=Some(loan.into_borrowed_parent());let demand=source_loan_transfer_demand();RetainedWorkOutcome{result:Ok(Some(RetainedCloneProgress{copied_items:1,copied_bytes:demand.copy_bytes,..Default::default()})),work:1}}
}
impl OriginalCallerSourceParent{
 /// 📤️ Returns the exact borrowed parent to its original live loan slot under Work.
 pub fn transfer_borrowed_loan(slot:&mut Option<Self>,output:&mut Option<OriginalCallerSourceLoan>,cx:&StepContext<'_>,effect:&mut RetainedAllocationEffect<'_>)->RetainedWorkOutcome<Option<RetainedCloneProgress>,ValueError>{let fail=|error|RetainedWorkOutcome{result:Err(error),work:0};if output.is_some(){return fail(refused("original Source loan output is occupied"))}let Some(parent)=slot.as_ref()else{return RetainedWorkOutcome{result:Ok(None),work:0}};if let Err(error)=parent.validate_borrowed_context(cx){return fail(error)}if !parent.borrowed_source||parent.original.is_none()||parent.retiring.is_some()||parent.pending_roots.is_some()||parent.pending_owner.is_some(){return fail(refused("borrowed Source parent still owns another frontier"))}match admit_source_loan_transfer(cx,effect){Ok(true)=>{},Ok(false)=>return RetainedWorkOutcome{result:Ok(None),work:0},Err((error,work))=>return RetainedWorkOutcome{result:Err(error),work}}let parent=slot.take().expect("validated borrowed Source parent");match parent.into_source_loan(){Ok(loan)=>{*output=Some(loan);let demand=source_loan_transfer_demand();RetainedWorkOutcome{result:Ok(Some(RetainedCloneProgress{copied_items:1,copied_bytes:demand.copy_bytes,..Default::default()})),work:1}},Err(parent)=>{*slot=Some(parent);RetainedWorkOutcome{result:Err(refused("borrowed Source parent changed during transfer")),work:1}}}}
}
